approach.optimized_pseudocode:
visited = empty set
count = 0
for each cell (r, c):
    if water or already visited:
        continue
    count += 1
    mark (r, c) visited
    stack = [(r, c)]
    while stack is not empty:
        (row, col) = stack.pop()
        for each of its four neighbors:
            if neighbor is in bounds, land, and unvisited:
                mark neighbor visited
                stack.push(neighbor)
return count

solution.java:
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashSet;
import java.util.Set;

class Solution {
    public int numIslands(char[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return 0;
        }
        int rows = grid.length, cols = grid[0].length;
        Set<Long> visited = new HashSet<>();
        Deque<int[]> stack = new ArrayDeque<>();
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        int islands = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                long id = (long) r * cols + c;
                if (grid[r][c] != '1' || visited.contains(id)) continue;
                islands++; // A new connected component.
                visited.add(id);
                stack.push(new int[]{r, c});
                while (!stack.isEmpty()) {
                    int[] cell = stack.pop();
                    for (int[] d : directions) {
                        int nr = cell[0] + d[0], nc = cell[1] + d[1];
                        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                        long nextId = (long) nr * cols + nc;
                        // add returns true only for a newly visited cell.
                        if (grid[nr][nc] == '1' && visited.add(nextId)) {
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
        return islands;
    }
}

solution.javascript:
function numIslands(grid) {
    if (!grid.length || !grid[0].length) return 0;
    const rows = grid.length, cols = grid[0].length;
    const visited = new Set();
    const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    let islands = 0;
    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            const id = r * cols + c;
            if (grid[r][c] !== '1' || visited.has(id)) continue;
            islands++; // A new connected component.
            visited.add(id);
            const stack = [[r, c]];
            while (stack.length) {
                const [row, col] = stack.pop();
                for (const [dr, dc] of directions) {
                    const nr = row + dr, nc = col + dc;
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                    const nextId = nr * cols + nc;
                    if (grid[nr][nc] === '1' && !visited.has(nextId)) {
                        visited.add(nextId); // Mark before pushing.
                        stack.push([nr, nc]);
                    }
                }
            }
        }
    }
    return islands;
}
